+  // Within each maximal region of changes, emit all deletes before inserts.
+  const script = [];
+  const pending = [];
+  for (const entry of raw) {
+    if (entry.op === 'equal') {
+      flushChanges(script, pending);
+      script.push(entry);
+    } else {
+      pending.push(entry);
+    }
+  }
+  flushChanges(script, pending);
+  return script;
