+/** Append a minimal script for a[aLo, aHi) -> b[bLo, bHi) to out (linear-space Myers). */
+function diffRange(a, b, ai, bi, aLo, aHi, bLo, bHi, out) {
+  let prefix = 0;
+  while (aLo < aHi && bLo < bHi && ai[aLo] === bi[bLo]) {
+    aLo++;
+    bLo++;
+    prefix++;
+  }
+  for (let i = aLo - prefix; i < aLo; i++) out.push({ op: 'equal', line: a[i] });
+
+  let suffix = 0;
+  while (aLo < aHi && bLo < bHi && ai[aHi - 1] === bi[bHi - 1]) {
+    aHi--;
+    bHi--;
+    suffix++;
+  }
+
+  if (aLo === aHi) {
+    for (let j = bLo; j < bHi; j++) out.push({ op: 'insert', line: b[j] });
+  } else if (bLo === bHi) {
+    for (let i = aLo; i < aHi; i++) out.push({ op: 'delete', line: a[i] });
+  } else {
+    const [x, y] = middleSnake(ai, bi, aLo, aHi, bLo, bHi);
+    diffRange(a, b, ai, bi, aLo, aLo + x, bLo, bLo + y, out);
+    diffRange(a, b, ai, bi, aLo + x, aHi, bLo + y, bHi, out);
+  }
+
+  for (let i = aHi; i < aHi + suffix; i++) out.push({ op: 'equal', line: a[i] });
+}
