+/**
+ * Find a split point (x, y), relative to aLo/bLo, lying on a minimal edit path.
+ * Both ranges are nonempty and differ at their first and last elements.
+ */
+function middleSnake(ai, bi, aLo, aHi, bLo, bHi) {
+  const n = aHi - aLo;
+  const m = bHi - bLo;
+  const maxD = Math.ceil((n + m) / 2);
+  const offset = maxD;
+  const size = 2 * maxD + 2;
+  const vf = new Int32Array(size).fill(-1);
+  const vb = new Int32Array(size).fill(-1);
+  vf[offset + 1] = 0;
+  vb[offset + 1] = 0;
+  const delta = n - m;
+  const front = (delta & 1) !== 0;
+  let kfStart = 0;
+  let kfEnd = 0;
+  let kbStart = 0;
+  let kbEnd = 0;
+
+  for (let d = 0; d <= maxD; d++) {
+    // Forward search from (0, 0).
+    for (let k = -d + kfStart; k <= d - kfEnd; k += 2) {
+      const kOff = offset + k;
+      let x;
+      if (k === -d || (k !== d && vf[kOff - 1] < vf[kOff + 1])) x = vf[kOff + 1];
+      else x = vf[kOff - 1] + 1;
+      let y = x - k;
+      while (x < n && y < m && ai[aLo + x] === bi[bLo + y]) {
+        x++;
+        y++;
+      }
+      vf[kOff] = x;
+      if (x > n) {
+        kfEnd += 2;
+      } else if (y > m) {
+        kfStart += 2;
+      } else if (front) {
+        const bOff = offset + delta - k;
+        if (bOff >= 0 && bOff < size && vb[bOff] !== -1 && x >= n - vb[bOff]) return [x, y];
+      }
+    }
+    // Reverse search from (n, m); vb stores distance travelled back from the end.
+    for (let k = -d + kbStart; k <= d - kbEnd; k += 2) {
+      const kOff = offset + k;
+      let x;
+      if (k === -d || (k !== d && vb[kOff - 1] < vb[kOff + 1])) x = vb[kOff + 1];
+      else x = vb[kOff - 1] + 1;
+      let y = x - k;
+      while (x < n && y < m && ai[aHi - 1 - x] === bi[bHi - 1 - y]) {
+        x++;
+        y++;
+      }
+      vb[kOff] = x;
+      if (x > n) {
+        kbEnd += 2;
+      } else if (y > m) {
+        kbStart += 2;
+      } else if (!front) {
+        const fOff = offset + delta - k;
+        if (fOff >= 0 && fOff < size && vf[fOff] !== -1) {
+          const fx = vf[fOff];
