+  const regions = [];
+  for (let i = 0; i < total;) {
+    if (script[i].op === 'equal') {
+      i++;
+      continue;
+    }
+    const start = i;
+    while (i < total && script[i].op !== 'equal') i++;
+    regions.push([start, i]);
+  }
