'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
  return dp[a.length][b.length];
}
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
const alphabet = ['', 'x', 'y', ' x', '-x', '+x', '__proto__', 'z'];
for (let iter = 0; iter < 20000; iter++) {
  const sym = 1 + rnd(alphabet.length);
  const a = Array.from({ length: rnd(14) }, () => alphabet[rnd(sym)]);
  const b = Array.from({ length: rnd(14) }, () => alphabet[rnd(sym)]);
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  const changes = s.filter((e) => e.op !== 'equal').length;
  assert.equal(changes, a.length + b.length - 2 * lcs(a, b), JSON.stringify([a, b]));
  for (let i = 1; i < s.length; i++) assert.ok(!(s[i - 1].op === 'insert' && s[i].op === 'delete'));
  assert.deepEqual(diffLines(a, b), s);
  for (const context of [0, 1, 2, 3]) {
    const h = unifiedHunks(a, b, { context });
    if (a.join('\n') === b.join('\n') && a.length === b.length) assert.deepEqual(h, []);
    assert.deepEqual(applyHunks(a, h), b);
    for (const x of h) {
      assert.equal(x.lines.filter((l) => l[0] !== '+').length, x.oldLines);
      assert.equal(x.lines.filter((l) => l[0] !== '-').length, x.newLines);
      // Validate coordinates against complete arrays.
      const ob = x.oldLines ? x.oldStart - 1 : x.oldStart;
      const nb = x.newLines ? x.newStart - 1 : x.newStart;
      assert.deepEqual(x.lines.filter((l) => l[0] !== '+').map((l) => l.slice(1)), a.slice(ob, ob + x.oldLines));
      assert.deepEqual(x.lines.filter((l) => l[0] !== '-').map((l) => l.slice(1)), b.slice(nb, nb + x.newLines));
    }
  }
  assert.deepEqual(a, ac);
  assert.deepEqual(b, bc);
}
