const a = ['a', 'b', 'c'];
const h = unifiedHunks(a, ['a', 'B', 'c'], { context: 0 });
assert.deepEqual(h, [{ oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] }]);
assert.throws(() => applyHunks(['a', 'x', 'c'], h), /hunk 0 does not apply/);
assert.throws(() => applyHunks(a, [h[0], h[0]]), /hunk 1 does not apply/);
assert.throws(() => applyHunks(a, [{ ...h[0], newStart: 3 }]), /hunk 0 does not apply/);
assert.deepEqual(unifiedHunks([], ['x']), [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] }]);
assert.deepEqual(unifiedHunks(['x'], []), [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-x'] }]);

// Performance.
const big = Array.from({ length: 20000 }, (_, i) => `line ${i % 7}`);
const big2 = big.slice();
