big2.splice(5000, 0, 'ins');
big2.splice(15000, 3);
let t = process.hrtime.bigint();
const hb = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, hb), big2);
console.log('small change ms', Number(process.hrtime.bigint() - t) / 1e6);
t = process.hrtime.bigint();
diffLines(big, big.slice());
console.log('identical ms', Number(process.hrtime.bigint() - t) / 1e6);
const r1 = Array.from({ length: 20000 }, () => 'a' + rnd(50));
const r2 = Array.from({ length: 20000 }, () => 'a' + rnd(50));
t = process.hrtime.bigint();
const sr = diffLines(r1, r2);
console.log('random 20k ms', Number(process.hrtime.bigint() - t) / 1e6, sr.length);
console.log('ok');
